195	func TestGitMetadataGuardAllowsSymlinkedRepoWithSafePhysicalAncestor(t *testing.T) {
196		repo := t.TempDir()
197		checkout := filepath.Join(repo, "checkout")
198		gitDir := filepath.Join(checkout, ".git")
199		for _, dir := range []string{
200			filepath.Join(checkout, "subdir"),
201			filepath.Join(gitDir, "objects"),
