	root, err := newSweepDirectoryRoot(resolvedRepo)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()

	if err := os.Rename(repo, filepath.Join(parent, "moved")); err != nil {
		t.Fatal(err)
