//go:build linux || darwin || dragonfly || freebsd || openbsd

package sem

import (
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

func TestSameVolumePathResolverChecksMountBeforeLstat(t *testing.T) {
	repo := t.TempDir()
	resolver, err := newSameVolumePathResolver(repo)
	if err != nil {
		t.Fatal(err)
	}
	defer resolver.Close()

	candidate := filepath.Join(repo, "metadata-that-does-not-exist")
	if _, err := os.Lstat(candidate); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("candidate Lstat error = %v, want a missing path", err)
	}
	resolver.mounts.addMountPoint(filepath.Clean(resolver.anchor.mapBase(candidate)))

	opened, _, err := resolver.open(candidate)
	if opened != nil {
		_ = opened.Close()
		t.Fatalf("resolver opened synthetic mount point %q", candidate)
	}
	if !errors.Is(err, errPathCrossesKnownMount) {
		t.Fatalf("resolver error for nonexistent synthetic mount point = %v, want %v", err, errPathCrossesKnownMount)
	}
}

func TestSameVolumePathResolverRejectsKnownMountBeforeLookup(t *testing.T) {
	resolver, err := newSameVolumePathResolver(string(filepath.Separator))
	if err != nil {
		t.Fatal(err)
	}
	defer resolver.Close()

	root := resolver.mounts.root
	candidates := make([]string, 0, len(resolver.mounts.mountPoints))
	for mount := range resolver.mounts.mountPoints {
		rel, err := filepath.Rel(root, mount)
		if err != nil || rel == "." || filepath.IsAbs(rel) || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			continue
		}
		candidates = append(candidates, mount)
	}
	if len(candidates) == 0 {
		t.Skip("host exposes no nested mount point beneath the filesystem root")
	}
	// Prefer a shallow system mount such as /proc or /dev so only ordinary,
	// local ancestors are inspected before the mount-table guard fires.
	sort.Slice(candidates, func(i, j int) bool {
		left := len(splitNativePathComponents(candidates[i]))
		right := len(splitNativePathComponents(candidates[j]))
		if left != right {
			return left < right
		}
		return candidates[i] < candidates[j]
	})

	opened, _, err := resolver.open(candidates[0])
	if opened != nil {
		_ = opened.Close()
		t.Fatalf("resolver opened known mount point %q", candidates[0])
	}
	if !errors.Is(err, errPathCrossesKnownMount) {
		t.Fatalf("resolver error for known mount point %q = %v, want %v", candidates[0], err, errPathCrossesKnownMount)
	}
}
package sem

import (
	"path/filepath"
	"strings"
)

// pathMountGuard confines candidate lookups to the deepest mounted filesystem
// that already contains the explicitly selected repository. Reaching that
// mount is trusted; entering a nested mount, or walking sideways back out of
// it, is not.
type pathMountGuard struct {
	enabled       bool
	root          string
	selectedMount string
	mountPoints   map[string]struct{}
	mountKeys     map[string]struct{}
}

func makePathMountGuard(root, trustedBase string, mountPoints map[string]struct{}) pathMountGuard {
	root = filepath.Clean(root)
	trustedBase = filepath.Clean(trustedBase)
	guard := pathMountGuard{
		enabled:       true,
		root:          root,
		selectedMount: root,
		mountPoints:   make(map[string]struct{}, len(mountPoints)),
		mountKeys:     make(map[string]struct{}, len(mountPoints)),
	}
	for mount := range mountPoints {
		mount = filepath.Clean(mount)
		guard.addMountPoint(mount)
		if mountPathContains(mount, trustedBase) && len(splitNativePathComponents(mount)) > len(splitNativePathComponents(guard.selectedMount)) {
			guard.selectedMount = mount
		}
	}
	return guard
}

func (g *pathMountGuard) addMountPoint(mount string) {
	if g.mountPoints == nil {
		g.mountPoints = make(map[string]struct{})
	}
	if g.mountKeys == nil {
		g.mountKeys = make(map[string]struct{})
	}
	mount = filepath.Clean(mount)
	g.mountPoints[mount] = struct{}{}
	g.mountKeys[mountPathKey(mount)] = struct{}{}
}

func (g pathMountGuard) beforeLookup(rel string) error {
	if !g.enabled {
		return nil
	}
	candidate := filepath.Clean(filepath.Join(g.root, rel))
	if mountPathContains(candidate, g.selectedMount) {
		// These are the already-trusted ancestors needed to reach the selected
		// mount, including the selected mount itself.
