		t.Error("excluded(\"vendor/dep/.dep-git/config\") = false after observing vendor/dep, want true")
	}
	if excluder.excluded("vendor/dep/src/app.go") {
		t.Error("excluded(\"vendor/dep/src/app.go\") = true, want false")
	}
}

