func TestGitDirExcluderKeepsSourceTreeNamedLikeAGitDir(t *testing.T) {
	t.Parallel()
	repo := t.TempDir()
	writeFile(t, repo, "testdata/parser/HEAD", "HEAD,BODY,TAIL\n")
