type sweepDirectoryRoot struct {
	root   *os.Root
	mounts pathMountGuard
}

func newSweepDirectoryRoot(repo string) (*sweepDirectoryRoot, error) {
	root, err := os.OpenRoot(repo)
	if err != nil {
		return nil, err
	}
	mounts, err := newPathMountGuard(repo, repo)
	if err != nil {
		_ = root.Close()
		return nil, err
	}
	return &sweepDirectoryRoot{root: root, mounts: mounts}, nil
}

func (r *sweepDirectoryRoot) Close() error { return r.root.Close() }

func (r *sweepDirectoryRoot) Open(anchor pathTraversalAnchor, dir string, admitStep func() bool) (*os.File, error) {
	rel := filepath.FromSlash(dir)
	if filepath.IsAbs(rel) || filepath.VolumeName(rel) != "" {
		return nil, errSymlinkChainOffVolume
	}
	components := splitNativePathComponents(rel)
	current := r.root
	resolved := make([]string, 0, len(components))
	var owned *os.Root
	defer func() {
		if owned != nil {
			_ = owned.Close()
		}
	}()

	if len(components) == 0 && !admitStep() {
		return nil, errGitDirSweepHalted
	}
	for _, component := range components {
		if component == ".." {
			return nil, errSymlinkChainOffVolume
		}
		if !admitStep() {
			return nil, errGitDirSweepHalted
		}
		candidate := filepath.Join(append(append([]string(nil), resolved...), component)...)
		if err := r.mounts.beforeLookup(candidate); err != nil {
			return nil, err
		}
		info, err := current.Lstat(component)
		if err != nil {
			return nil, err
		}
		// The sweep is built only from real directory entries and never needs
		// redirect semantics. Rejecting links and reparse points before opening
		// them keeps an ignored tree from steering the scan outside the held
		// repository root; the device check similarly refuses POSIX mount points.
		if pathMayRedirect(info) || !anchor.allows(info) {
			return nil, errSymlinkChainOffVolume
		}
		if !info.IsDir() {
			return nil, fs.ErrInvalid
		}
		next, err := current.OpenRoot(component)
		if err != nil {
			return nil, err
		}
		openedInfo, err := next.Stat(".")
		if err != nil || !openedInfo.IsDir() || !anchor.allows(openedInfo) || !os.SameFile(info, openedInfo) {
			_ = next.Close()
			if err != nil {
				return nil, err
			}
			return nil, errSymlinkChainOffVolume
		}
		if owned != nil {
			_ = owned.Close()
		}
		owned = next
		current = next
		resolved = append(resolved, component)
	}

	opened, err := current.Open(".")
	if err != nil {
		return nil, err
	}
	info, err := opened.Stat()
	if err != nil || !info.IsDir() || !anchor.allows(info) {
		_ = opened.Close()
		if err != nil {
			return nil, err
		}
		return nil, errSymlinkChainOffVolume
	}
	return opened, nil
}
//go:build linux

package sem

import (
	"bufio"
	"errors"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"syscall"
	"unsafe"
)

type sweepDirectoryRoot struct {
	file *os.File

	mountOnce   sync.Once
	mountPoints map[string]struct{}
	mountErr    error
}

func newSweepDirectoryRoot(repo string) (*sweepDirectoryRoot, error) {
	file, err := os.Open(repo)
	if err != nil {
		return nil, err
	}
	return &sweepDirectoryRoot{file: file}, nil
}

func (r *sweepDirectoryRoot) Close() error { return r.file.Close() }

type linuxOpenHow struct {
	flags   uint64
	mode    uint64
	resolve uint64
}

const (
	linuxResolveNoXDev      = 0x01
	linuxResolveNoMagicLink = 0x02
	linuxResolveNoSymlink   = 0x04
	linuxResolveBeneath     = 0x08
)

func linuxOpenat2Number() uintptr {
	switch runtime.GOARCH {
	case "mips", "mipsle":
		return 4437
	case "mips64", "mips64le":
		return 5437
	default:
		return 437
	}
}

func (r *sweepDirectoryRoot) openat2(rel string) (*os.File, error) {
	name, err := syscall.BytePtrFromString(rel)
	if err != nil {
		return nil, err
	}
	how := linuxOpenHow{
		flags: uint64(syscall.O_RDONLY | syscall.O_CLOEXEC | syscall.O_DIRECTORY),
		resolve: linuxResolveNoXDev | linuxResolveNoMagicLink |
			linuxResolveNoSymlink | linuxResolveBeneath,
	}
	fd, _, errno := syscall.Syscall6(
		linuxOpenat2Number(),
		r.file.Fd(),
		uintptr(unsafe.Pointer(name)),
		uintptr(unsafe.Pointer(&how)),
		unsafe.Sizeof(how),
		0,
		0,
	)
	if errno != 0 {
		return nil, errno
	}
	opened := os.NewFile(fd, filepath.Join(r.file.Name(), rel))
	if opened == nil {
		_ = syscall.Close(int(fd))
		return nil, fs.ErrInvalid
	}
	return opened, nil
}

const (
	maxLinuxMountInfoBytes = 16 << 20
	maxLinuxMountInfoLines = 100_000
)

var linuxMountInfoEscapes = strings.NewReplacer(
	`\040`, " ",
	`\011`, "\t",
	`\012`, "\n",
	`\134`, `\`,
)

func readLinuxMountPoints() (map[string]struct{}, error) {
	file, err := os.Open("/proc/self/mountinfo")
	if err != nil {
		return nil, err
	}
	defer file.Close()
	limited := &io.LimitedReader{R: file, N: maxLinuxMountInfoBytes + 1}
	scanner := bufio.NewScanner(limited)
	scanner.Buffer(make([]byte, 4096), 1<<20)
	mounts := make(map[string]struct{})
	for lines := 0; scanner.Scan(); lines++ {
		if lines >= maxLinuxMountInfoLines {
			return nil, errors.New("Linux mount table exceeded its line bound")
		}
		fields := strings.Fields(scanner.Text())
		if len(fields) < 5 {
			return nil, errors.New("malformed Linux mount table entry")
		}
		mounts[filepath.Clean(linuxMountInfoEscapes.Replace(fields[4]))] = struct{}{}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if limited.N <= 0 {
		return nil, errors.New("Linux mount table exceeded its byte bound")
	}
	return mounts, nil
}

func (r *sweepDirectoryRoot) loadMountPoints() (map[string]struct{}, error) {
	r.mountOnce.Do(func() {
		r.mountPoints, r.mountErr = readLinuxMountPoints()
	})
	return r.mountPoints, r.mountErr
}

func (r *sweepDirectoryRoot) openWithoutOpenat2(
	anchor pathTraversalAnchor,
	components []string,
	admitStep func() bool,
) (*os.File, error) {
	current := r.file
	currentPath := filepath.Clean(r.file.Name())
	var owned *os.File
	closeOwned := func() {
		if owned != nil {
			_ = owned.Close()
		}
	}

	if len(components) == 0 {
		fd, err := syscall.Dup(int(r.file.Fd()))
		if err != nil {
			return nil, err
		}
		opened := os.NewFile(uintptr(fd), r.file.Name())
		if opened == nil {
			_ = syscall.Close(fd)
			return nil, fs.ErrInvalid
		}
