package sem

import (
	"os"
	"testing"
	"time"
)

func TestMetadataGuardCurrentRepositoryTiming(t *testing.T) {
	repo := os.Getenv("ENTIRE_GRAPH_METADATA_PERF_REPO")
	if repo == "" {
		t.Skip("timing repository not requested")
	}
	started := time.Now()
	if !gitMetadataSafeForSubprocess(repo) {
		t.Fatal("current repository metadata refused")
	}
	t.Logf("metadata guard duration: %s", time.Since(started))
}

