func gitMetadataDirectoryPathsSafe(repoRoot, gitDir string) bool {
	resolver, err := newSameVolumePathResolver(repoRoot)
	if err != nil {
		return false
	}
	defer resolver.Close()
	return gitMetadataDirectoryPathsSafeWithResolver(resolver, gitDir)
