	select {
	case safe := <-done:
		if safe {
			t.Fatalf("UNC redirect at %s passed the pre-subprocess metadata guard", label)
		}
	case <-time.After(5 * time.Second):
		t.Fatalf("UNC redirect at %s was followed instead of being rejected before network access", label)
	}
}

